insert into public.car_community_notes (id, car_id, body, source_id, created_at) values
  ('dafc5d67-ed84-5278-bf54-231a3a1e080a', 'c0000000-0000-0000-0000-000000000001', 'The canopy tint shifts between smoke and blue across factories — both are legitimate, neither is a chase.', '3b56013f-2bc0-5ad5-a19b-19927e730ca9', now() - interval '1 days'),
  ('c9cc0329-2b8a-57df-9aa4-3c348d9d5768', 'c0000000-0000-0000-0000-000000000001', 'Check the engine chrome before you buy: early cases had flaking on the left blower.', 'fd3ee9d3-5456-51d8-af60-86884e9a5ffa', now() - interval '4 days'),
  ('6f863a69-c58f-579a-810b-ccc167796110', 'c0000000-0000-0000-0000-000000000001', 'One of five Art Cars this year that spell a hidden word across the series when lined up.', 'bd4d279b-61be-5902-a306-4f34d54445ec', now() - interval '7 days')
