insert into public.car_community_notes (id, car_id, body, source_id, created_at) values
  ('15781030-f782-5a95-b9c0-cc2a0291ae3e', 'c0000000-0000-0000-0000-000000000002', 'Fastest way to spot it on a full peg: look for the red wheel rims, not the gold paint.', '3b56013f-2bc0-5ad5-a19b-19927e730ca9', now() - interval '1 days'),
  ('bb188389-4d3f-59f4-944b-261e8328768d', 'c0000000-0000-0000-0000-000000000002', 'Found three at one store on a Tuesday morning restock. Overnight stockers put the fresh cases at the back.', 'fd3ee9d3-5456-51d8-af60-86884e9a5ffa', now() - interval '4 days'),
  ('079b2649-fb27-529e-930d-0a0efb65b0ab', 'c0000000-0000-0000-0000-000000000002', 'Our pick for the most photogenic Treasure Hunt of the year.', 'bd4d279b-61be-5902-a306-4f34d54445ec', now() - interval '7 days'),
