  ('c3f3773d-ccf6-5dac-89bf-191115031124', 'c0000000-0000-0000-0000-000000000005', 'If a store has a fresh Case E, this is the first car gone. Ask for the unopened box.', 'fd3ee9d3-5456-51d8-af60-86884e9a5ffa', now() - interval '1 days'),
